#!/usr/bin/env bash
# JDBC objects (jdbc:objects) and JDBC driver dispatch
# (service-provider:dispatch) oracle (ROADMAP B4). Builds testdata/jdbc into
# five jars:
#   deps/stub.jar    abstract stubs of Connection, PreparedStatement and
#                    ResultSet (generated by scripts/JdbcStubs.java), and
#                    fx.trace.Ran
#   deps/driver.jar  a driver registered in META-INF/services/java.sql.Driver,
#                    its connection, statement and result set, and a
#                    statement only an uncalled method creates
#   deps/pool.jar    a DataSource handing out proxy connections and proxy
#                    statements that inherit executeQuery (Hikari-shaped)
#   deps/other.jar   statements outside driver and pool, never created
#   app.jar          fx.app.Main: one query through DriverManager, one
#                    through the pool
# and runs Main on the real JVM, which prints every body that ran. Writes
# testdata/jdbc/observed.txt; the jars and the file are committed, and
# cmd/ariadne TestJDBCOracle checks the graph against them without a JDK.
#
# Usage: scripts/jdbc-oracle.sh [JAVA_HOME]
set -euo pipefail
JAVA_HOME_ARG="${1:-${JAVA_HOME:-}}"
if [ -n "$JAVA_HOME_ARG" ]; then
    export JAVA_HOME="$JAVA_HOME_ARG"
    export PATH="$JAVA_HOME/bin:$PATH"
fi
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
fx="$root/testdata/jdbc"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
mkdir -p "$fx/deps" "$tmp/stub/fx/stub"
cp -r "$fx/stub/." "$tmp/stub/"
java "$root/scripts/JdbcStubs.java" "$tmp/stub/fx/stub" fx.stub java.sql.Connection java.sql.PreparedStatement java.sql.ResultSet
java "$root/scripts/JavaBuild.java" "$tmp/stub" "$fx/deps/stub.jar" 17
java "$root/scripts/JavaBuild.java" "$fx/driver" "$fx/deps/driver.jar" 17 "$fx/deps/stub.jar"
java "$root/scripts/JavaBuild.java" "$fx/pool" "$fx/deps/pool.jar" 17 "$fx/deps/stub.jar"
java "$root/scripts/JavaBuild.java" "$fx/other" "$fx/deps/other.jar" 17 "$fx/deps/stub.jar"
java "$root/scripts/JavaBuild.java" "$fx/app" "$fx/app.jar" 17 "$fx/deps/stub.jar:$fx/deps/pool.jar"
cat > "$tmp/AddResources.java" <<'J'
import java.util.spi.ToolProvider;
public class AddResources {
    public static void main(String[] a) {
        System.exit(ToolProvider.findFirst("jar").orElseThrow().run(System.out, System.err,
            "--update", "--file", a[0], "--date", "2026-01-01T00:00:00Z", "-C", a[1], "."));
    }
}
J
java "$tmp/AddResources.java" "$fx/deps/driver.jar" "$fx/driver-resources"
{
    echo "# generated by scripts/jdbc-oracle.sh on $(java -version 2>&1 | head -1)"
    java -cp "$fx/app.jar:$fx/deps/stub.jar:$fx/deps/driver.jar:$fx/deps/pool.jar:$fx/deps/other.jar" fx.app.Main
} > "$fx/observed.txt"
cat "$fx/observed.txt"
